# 3. Deterministic Arena Scope and Zero Leak
let total = 0.0

for i in range(0, 5):
    let step_tensor = tensor([1.0, 2.0, 3.0]) * (i + 1)
    let step_sum = step_tensor.sum()
    total = total + step_sum
    print("Adim:", i, "Ara Toplam:", total)

print("Nihai Toplam:", total)

# 4. Type-Safe Option/Result and Match
fn find_user_score(id: int) -> Option[int]:
    if id == 42:
        return Option.Some(100)
    return Option.None

let score_opt = find_user_score(42)

match score_opt:
    case Option.Some(score):
        print("Kullanici skoru bulundu:", score)
    case Option.None:
        print("Kullanici bulunamadi.")

# 5. No-GIL Lightweight Concurrency and Channels
let ch = Channel(2)

fn producer():
    ch.send("Synapse Ajan 1 basariyla tamamlandi.")
    ch.send("Synapse Ajan 2 veri aktardi.")

let worker = spawn(producer)
let msg1 = ch.receive()
let msg2 = ch.receive()

print("Alinan Mesaj 1:", msg1)
print("Alinan Mesaj 2:", msg2)

